    .duration_since(std::time::UNIX_EPOCH)
    .map(|d| d.as_nanos() as u64)
    .unwrap_or(0x9E37_79B9_7F4A_7C15)
    ^ n.wrapping_mul(0x9E37_79B9_7F4A_7C15))
    | 1;
for _ in 0..4 {
    seed ^= seed << 13;
    seed ^= seed >> 7;
    seed ^= seed << 17;
}

